    public static FfiConverterTypeWithReplyKeyTransition INSTANCE = new FfiConverterTypeWithReplyKeyTransition();


    public override ulong Lower(WithReplyKeyTransition value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override WithReplyKeyTransition Lift(ulong value) {
        return new WithReplyKeyTransition(value);
    }

    public override WithReplyKeyTransition Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(WithReplyKeyTransition value) {
        return 8;
    }

    public override void Write(WithReplyKeyTransition value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



