/// <summary>
/// Represents data that needs to be transmitted to the receiver.
/// You need to send this request over HTTP(S) to the receiver.
/// </summary>
/// <param name="Url">
/// URL to send the request to.
/// 
/// This is full URL with scheme etc - you can pass it right to `reqwest` or a similar library.
/// </param>
/// <param name="ContentType">
/// The `Content-Type` header to use for the request.
/// 
/// `text/plain` for v1 requests and `message/ohttp-req` for v2 requests.
/// </param>
/// <param name="Body">
/// Bytes to be sent to the receiver.
/// 
/// This is properly encoded PSBT payload either in base64 in v1 or an OHTTP encapsulated payload in v2.
/// </param>
internal record Request (
    /// <summary>
    /// URL to send the request to.
    ///
    /// This is full URL with scheme etc - you can pass it right to `reqwest` or a similar library.
    /// </summary>
    string Url, 
    /// <summary>
    /// The `Content-Type` header to use for the request.
    ///
    /// `text/plain` for v1 requests and `message/ohttp-req` for v2 requests.
    /// </summary>
    string ContentType, 
    /// <summary>
    /// Bytes to be sent to the receiver.
    ///
    /// This is properly encoded PSBT payload either in base64 in v1 or an OHTTP encapsulated payload in v2.
    /// </summary>
    byte[] Body
) {
}

class FfiConverterTypeRequest: FfiConverterRustBuffer<Request> {
    public static FfiConverterTypeRequest INSTANCE = new FfiConverterTypeRequest();

    public override Request Read(BigEndianStream stream) {
        return new Request(
            Url: FfiConverterString.INSTANCE.Read(stream),
            ContentType: FfiConverterString.INSTANCE.Read(stream),
            Body: FfiConverterByteArray.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(Request value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Url)
            + FfiConverterString.INSTANCE.AllocationSize(value.ContentType)
            + FfiConverterByteArray.INSTANCE.AllocationSize(value.Body);
    }

    public override void Write(Request value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Url, stream);
            FfiConverterString.INSTANCE.Write(value.ContentType, stream);
            FfiConverterByteArray.INSTANCE.Write(value.Body, stream);
    }
}



