/// <summary>
/// BIP-78 well-known error code, surfaced to bindings so senders can branch
/// on the code instead of parsing the Display string.
/// </summary>
internal enum ErrorCode: int {
    /// <summary>
    /// The payjoin endpoint is not available for now.
    /// </summary>
    Unavailable,
    /// <summary>
    /// The receiver added some inputs but could not bump the fee.
    /// </summary>
    NotEnoughMoney,
    /// <summary>
    /// This version of payjoin is not supported.
    /// </summary>
    VersionUnsupported,
    /// <summary>
    /// The receiver rejected the original PSBT.
    /// </summary>
    OriginalPsbtRejected,
    /// <summary>
    /// A well-known code newer than this binding understands.
    /// </summary>
    Unrecognized
}

class FfiConverterTypeErrorCode: FfiConverterRustBuffer<ErrorCode> {
    public static FfiConverterTypeErrorCode INSTANCE = new FfiConverterTypeErrorCode();

    public override ErrorCode Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return ErrorCode.Unavailable;
            case 2: return ErrorCode.NotEnoughMoney;
            case 3: return ErrorCode.VersionUnsupported;
            case 4: return ErrorCode.OriginalPsbtRejected;
            case 5: return ErrorCode.Unrecognized;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeErrorCode.Read()", value));
        }
    }

    public override int AllocationSize(ErrorCode value) {
        return 4;
    }

    public override void Write(ErrorCode value, BigEndianStream stream) {
        switch (value) {
            case ErrorCode.Unavailable: stream.WriteInt(1); break;
            case ErrorCode.NotEnoughMoney: stream.WriteInt(2); break;
            case ErrorCode.VersionUnsupported: stream.WriteInt(3); break;
            case ErrorCode.OriginalPsbtRejected: stream.WriteInt(4); break;
            case ErrorCode.Unrecognized: stream.WriteInt(5); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeErrorCode.Write()", value));
        }
    }
}







internal class FfiException: UniffiException {
    FfiException() : base() {}
    FfiException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class InitException : FfiException {
        // Members
        public string @v1;

        // Constructor
        public InitException(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class RpcException : FfiException {
        // Members
        public string @v1;

        // Constructor
        public RpcException(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class Message : FfiException {
        // Members
        public string @v1;

        // Constructor
        public Message(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    

    
}

class FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException>, CallStatusErrorHandler<FfiException> {
    public static FfiConverterTypeFfiError INSTANCE = new FfiConverterTypeFfiError();

    public override FfiException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new FfiException.InitException(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new FfiException.RpcException(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new FfiException.Message(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.Read()", value));
        }
    }

    public override int AllocationSize(FfiException value) {
        switch (value) {

            case FfiException.InitException variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);

            case FfiException.RpcException variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);

            case FfiException.Message variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.AllocationSize()", value));
        }
    }

    public override void Write(FfiException value, BigEndianStream stream) {
        switch (value) {
            case FfiException.InitException variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@v1, stream);
                break;
            case FfiException.RpcException variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@v1, stream);
                break;
            case FfiException.Message variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@v1, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.Write()", value));
        }
    }
}





internal class FfiValidationException: UniffiException {
    FfiValidationException() : base() {}
    FfiValidationException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class AmountOutOfRange : FfiValidationException {
        // Members
        public ulong @amountSat;
        public ulong @maxSat;

        // Constructor
        public AmountOutOfRange(
                ulong @amountSat, 
                ulong @maxSat) : base(
                "@amountSat" + "=" + @amountSat+ ", " +
                "@maxSat" + "=" + @maxSat) {

            this.@amountSat = @amountSat;

            this.@maxSat = @maxSat;
        }
    }
    
    
    public class ScriptEmpty : FfiValidationException {
        // Members
        public string @field;

        // Constructor
        public ScriptEmpty(
                string @field) : base(
                "@field" + "=" + @field) {

            this.@field = @field;
        }
    }
    
    
    public class ScriptTooLarge : FfiValidationException {
        // Members
        public string @field;
        public ulong @len;
        public ulong @max;

        // Constructor
        public ScriptTooLarge(
                string @field, 
                ulong @len, 
                ulong @max) : base(
                "@field" + "=" + @field+ ", " +
                "@len" + "=" + @len+ ", " +
                "@max" + "=" + @max) {

            this.@field = @field;

            this.@len = @len;

            this.@max = @max;
        }
    }
    
    
    public class WitnessItemsTooMany : FfiValidationException {
        // Members
        public ulong @count;
        public ulong @max;

        // Constructor
        public WitnessItemsTooMany(
                ulong @count, 
                ulong @max) : base(
                "@count" + "=" + @count+ ", " +
                "@max" + "=" + @max) {

            this.@count = @count;

            this.@max = @max;
        }
    }
    
    
    public class WitnessItemTooLarge : FfiValidationException {
        // Members
        public ulong @index;
        public ulong @len;
        public ulong @max;

        // Constructor
        public WitnessItemTooLarge(
                ulong @index, 
                ulong @len, 
                ulong @max) : base(
                "@index" + "=" + @index+ ", " +
                "@len" + "=" + @len+ ", " +
                "@max" + "=" + @max) {

            this.@index = @index;

            this.@len = @len;

            this.@max = @max;
        }
    }
    
    
    public class WitnessTooLarge : FfiValidationException {
        // Members
        public ulong @len;
        public ulong @max;

        // Constructor
        public WitnessTooLarge(
                ulong @len, 
                ulong @max) : base(
                "@len" + "=" + @len+ ", " +
                "@max" + "=" + @max) {

            this.@len = @len;

            this.@max = @max;
        }
    }
    
    
    public class WeightOutOfRange : FfiValidationException {
        // Members
        public ulong @weightUnits;
        public ulong @maxWu;

        // Constructor
        public WeightOutOfRange(
                ulong @weightUnits, 
                ulong @maxWu) : base(
                "@weightUnits" + "=" + @weightUnits+ ", " +
                "@maxWu" + "=" + @maxWu) {

            this.@weightUnits = @weightUnits;

            this.@maxWu = @maxWu;
        }
    }
    
    
    public class FeeRateOutOfRange : FfiValidationException {
        // Members
        public ulong @value;
        public string @unit;

        // Constructor
        public FeeRateOutOfRange(
                ulong @value, 
                string @unit) : base(
                "@value" + "=" + @value+ ", " +
                "@unit" + "=" + @unit) {

            this.@value = @value;

            this.@unit = @unit;
        }
    }
    
    
    public class ExpirationOutOfRange : FfiValidationException {
        // Members
        public ulong @seconds;
        public ulong @max;

        // Constructor
        public ExpirationOutOfRange(
                ulong @seconds, 
                ulong @max) : base(
                "@seconds" + "=" + @seconds+ ", " +
                "@max" + "=" + @max) {

            this.@seconds = @seconds;

            this.@max = @max;
        }
    }
    

    
}

class FfiConverterTypeFfiValidationError : FfiConverterRustBuffer<FfiValidationException>, CallStatusErrorHandler<FfiValidationException> {
    public static FfiConverterTypeFfiValidationError INSTANCE = new FfiConverterTypeFfiValidationError();

    public override FfiValidationException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new FfiValidationException.AmountOutOfRange(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream));
            case 2:
                return new FfiValidationException.ScriptEmpty(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new FfiValidationException.ScriptTooLarge(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream));
            case 4:
                return new FfiValidationException.WitnessItemsTooMany(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream));
            case 5:
                return new FfiValidationException.WitnessItemTooLarge(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream));
            case 6:
                return new FfiValidationException.WitnessTooLarge(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream));
            case 7:
                return new FfiValidationException.WeightOutOfRange(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream));
            case 8:
                return new FfiValidationException.FeeRateOutOfRange(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            case 9:
                return new FfiValidationException.ExpirationOutOfRange(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiValidationError.Read()", value));
        }
    }

    public override int AllocationSize(FfiValidationException value) {
        switch (value) {

            case FfiValidationException.AmountOutOfRange variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@amountSat)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@maxSat);

            case FfiValidationException.ScriptEmpty variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@field);

            case FfiValidationException.ScriptTooLarge variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@field)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@len)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@max);

            case FfiValidationException.WitnessItemsTooMany variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@count)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@max);

            case FfiValidationException.WitnessItemTooLarge variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@index)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@len)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@max);

            case FfiValidationException.WitnessTooLarge variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@len)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@max);

            case FfiValidationException.WeightOutOfRange variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@weightUnits)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@maxWu);

            case FfiValidationException.FeeRateOutOfRange variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@value)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@unit);

            case FfiValidationException.ExpirationOutOfRange variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@seconds)
