                stream.WriteInt(1);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@amountSat, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@maxSat, stream);
                break;
            case FfiValidationException.ScriptEmpty variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@field, stream);
                break;
            case FfiValidationException.ScriptTooLarge variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@field, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@len, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@max, stream);
                break;
            case FfiValidationException.WitnessItemsTooMany variant_value:
                stream.WriteInt(4);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@count, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@max, stream);
                break;
            case FfiValidationException.WitnessItemTooLarge variant_value:
                stream.WriteInt(5);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@index, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@len, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@max, stream);
                break;
            case FfiValidationException.WitnessTooLarge variant_value:
                stream.WriteInt(6);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@len, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@max, stream);
                break;
            case FfiValidationException.WeightOutOfRange variant_value:
                stream.WriteInt(7);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@weightUnits, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@maxWu, stream);
