            case FfiValidationException.FeeRateOutOfRange variant_value:
                stream.WriteInt(8);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@value, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@unit, stream);
                break;
            case FfiValidationException.ExpirationOutOfRange variant_value:
                stream.WriteInt(9);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@seconds, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@max, stream);
