/// <summary>
/// Error that may occur during state machine transitions
/// </summary>
internal class ReceiverPersistedException: UniffiException, IDisposable  {
    ReceiverPersistedException() : base() {}
    ReceiverPersistedException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// A transient error: nothing was persisted, and the failed transition
    /// can be retried by calling it again on the same receiver object
    /// </summary>
    
    public class Transient : ReceiverPersistedException {
        // Members
        public ReceiverException @v1;

        // Constructor
        public Transient(
                ReceiverException @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    /// <summary>
    /// A fatal error: the session is closed or has moved to an error state
    /// </summary>
    
    public class Fatal : ReceiverPersistedException {
        // Members
        public ReceiverException @v1;

        // Constructor
        public Fatal(
                ReceiverException @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    /// <summary>
    /// Storage error that could occur at application storage layer
    /// </summary>
    
    public class Storage : ReceiverPersistedException {
        // Members
        public ImplementationError @v1;

        // Constructor
        public Storage(
                ImplementationError @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    

    
    public void Dispose() {
        switch (this) {
            case ReceiverPersistedException.Transient variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            case ReceiverPersistedException.Fatal variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            case ReceiverPersistedException.Storage variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in ReceiverPersistedException.Dispose()", this));
        }
    }
    
}

