/// <summary>
/// Represent an error returned by Payjoin receiver.
/// </summary>
internal class ResponseException: UniffiException, IDisposable  {
    ResponseException() : base() {}
    ResponseException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// `WellKnown` Errors are defined in the [`BIP78::ReceiverWellKnownError`] spec.
    ///
    /// It is safe to display `WellKnown` errors to end users.
    ///
    /// [`BIP78::ReceiverWellKnownError`]: https://github.com/bitcoin/bips/blob/master/bip-0078.mediawiki#user-content-Receivers_well_known_errors
    /// </summary>
    
    public class WellKnown : ResponseException {
        // Members
        public WellKnownError @v1;

        // Constructor
        public WellKnown(
                WellKnownError @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    /// <summary>
    /// Errors caused by malformed responses.
    /// </summary>
    
    public class Validation : ResponseException {
        // Members
        public ValidationError @v1;

        // Constructor
        public Validation(
                ValidationError @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    /// <summary>
    /// `Unrecognized` Errors are NOT defined in the [`BIP78::ReceiverWellKnownError`] spec.
    ///
    /// It is NOT safe to display `Unrecognized` errors to end users as they could be used
    /// maliciously to phish a non technical user. Only display them in debug logs.
    ///
    /// [`BIP78::ReceiverWellKnownError`]: https://github.com/bitcoin/bips/blob/master/bip-0078.mediawiki#user-content-Receivers_well_known_errors
    /// </summary>
    
    public class Unrecognized : ResponseException {
        // Members
        public string @errorCode;
        public string @msg;

        // Constructor
        public Unrecognized(
                string @errorCode, 
                string @msg) : base(
                "@errorCode" + "=" + @errorCode+ ", " +
                "@msg" + "=" + @msg) {

            this.@errorCode = @errorCode;

            this.@msg = @msg;
        }
    }
    

    
    public void Dispose() {
        switch (this) {
            case ResponseException.WellKnown variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            case ResponseException.Validation variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            case ResponseException.Unrecognized variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@errorCode,
                    variant_value.@msg);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in ResponseException.Dispose()", this));
        }
    }
    
}

class FfiConverterTypeResponseError : FfiConverterRustBuffer<ResponseException>, CallStatusErrorHandler<ResponseException> {
    public static FfiConverterTypeResponseError INSTANCE = new FfiConverterTypeResponseError();

    public override ResponseException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ResponseException.WellKnown(
