                SenderException @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    /// <summary>
    /// Storage error that could occur at application storage layer
    /// </summary>
    
    public class Storage : SenderPersistedException {
        // Members
