        // Constructor
        public Storage(
                ImplementationError @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    

    
    public void Dispose() {
        switch (this) {
            case SenderPersistedException.Transient variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            case SenderPersistedException.Fatal variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            case SenderPersistedException.Storage variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.@v1);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in SenderPersistedException.Dispose()", this));
        }
    }
    
}

